include <robotics.scad>
// PCB: origin at board centre, bottom face z=0. Long side along X, USB edge at -X.
L = 62.74; W = 25.40; T = 1.6;   // T assumed
pitch = 2.54; n = 22;
x0 = 7.96 - L/2;                  // first pin from USB edge
row = 22.86/2;                    // rows at Y = ±11.43
drill = 1.0;                      // not published
difference() {
  translate([-L/2, -W/2, 0]) cube([L, W, T]);
  for (sy = [-1, 1], i = [0:n-1])
    translate([x0 + i*pitch, sy*row, -1]) cylinder(d = drill, h = T + 2, $fn = 24);
}

include <robotics.scad>
// Plain module envelope; origin at footprint centre, bottom on PCB top.
cuboid([25.5, 18.0, 3.1], anchor = BOT);

include <robotics.scad>
// Origin: header centre on the PCB bottom face. Pins down.
n = 22; p = 2.54; body_h = 2.5; tail = 6.0; pin = 0.64;
translate([0, 0, -body_h]) cuboid([n*p, p, body_h], chamfer = 0.3, anchor = BOT);
for (i = [0:n-1]) translate([(i - (n-1)/2)*p, 0, -body_h - tail])
  cuboid([pin, pin, body_h + tail + 1.6], anchor = BOT);   // pin top flush with PCB top

